(function(){
var _r = {};
try {
  var c = app.project.activeItem;
  if (!c || !(c instanceof CompItem)) {
    _r = {status: 'error', message: 'No active composition'};
    return JSON.stringify(_r);
  }
  var layerName = '{{targetLayerName}}';
  var L = null;
  for (var i = 1; i <= c.numLayers; i++) {
    if (c.layer(i).name === layerName) { L = c.layer(i); break; }
  }
  if (!L) {
    _r = {status: 'error', message: 'Layer not found: ' + layerName};
    return JSON.stringify(_r);
  }
  // === Style: 赛博朋克/霓虹风格 ===
  // Effect: Exposure (ADBE Exposure2)
var _ef = L.property('ADBE Effect Parade').addProperty('ADBE Exposure2');
_ef.property('ADBE Exposure2-0002').setValue(0.8);
// Effect: Lumetri Color (ADBE Lumetri)
var _ef = L.property('ADBE Effect Parade').addProperty('ADBE Lumetri');
_ef.property('ADBE Lumetri-0002').setValue(20);
_ef.property('ADBE Lumetri-0004').setValue(15);
// Effect: Fractal Noise (ADBE Fractal Noise)
var _ef = L.property('ADBE Effect Parade').addProperty('ADBE Fractal Noise');
_ef.property('ADBE Fractal Noise-0005').setValue(30);
_ef.property('ADBE Fractal Noise-0008').setValue(4);
_ef.property('ADBE Fractal Noise-0006').setValue(-20);
L.blendingMode = 22; // Overlay
L.opacity.setValue(35);
// Effect: Glow (ADBE Glo2)
var _ef = L.property('ADBE Effect Parade').addProperty('ADBE Glo2');
_ef.property('ADBE Glo2-0001').setValue(40);
_ef.property('ADBE Glo2-0002').setValue(35);
_ef.property('ADBE Glo2-0004').setValue([0, 200, 255]);
_ef.property('ADBE Glo2-0005').setValue([255, 0, 200]);
// Effect: Turbulent Displace (ADBE Turbulent Displace)
var _ef = L.property('ADBE Effect Parade').addProperty('ADBE Turbulent Displace');
_ef.property('ADBE Turbulent Displace-0001').setValue(15);
_ef.property('ADBE Turbulent Displace-0002').setValue(25);
  _r = {status: 'success', preset: 'cyberpunk_neon', layer: layerName};
} catch(e) {
  _r = {status: 'error', message: e.toString()};
}
return JSON.stringify(_r);
})();

